    msg.payload = { role: 'guest' };
    return msg;
}

const db = new Database('/root/Documents/data.db');
try {
    const sess = db.prepare("SELECT username, role FROM admin_sessions WHERE token = ? AND expires_at > datetime('now','localtime')").get(token);
    db.close();
    if (!sess) {
        msg.payload = { role: 'guest' };
    } else {
        msg.payload = { role: sess.role, username: sess.username };
    }
    return msg;
} catch(e) {
    db.close();
    msg.payload = { role: 'guest', error: e.message };
    return msg;
}

