function subIdx(c, bp) {
    if (c <= bp[0][0]) return bp[0][2];
    for (let i = 0; i < bp.length; i++) {
        const [cL, cH, iL, iH] = bp[i];
        if (c >= cL && c <= cH) return Math.round((iH - iL) / (cH - cL) * (c - cL) + iL);
    }
    return 500;
}

