    const start = new Date(now.getTime() - 3600 * 1000);
    const fmt = (d) => d.getFullYear() + '-' +
        String(d.getMonth() + 1).padStart(2, '0') + '-' +
        String(d.getDate()).padStart(2, '0') + ' ' +
        String(d.getHours()).padStart(2, '0') + ':00:00';
    const hourTs = fmt(start);
    const nextHour = fmt(now);

    // Aggregate raw → hourly
    const row = db.prepare('SELECT AVG(t) t, AVG(h) h, AVG(v) v, AVG(CASE WHEN i > 0 THEN i END) i_, AVG(pm1) pm1, AVG(pm25) pm25, AVG(pm10) pm10, AVG(co) co, AVG(voc) voc, AVG(nox) nox, COUNT(*) cnt FROM sensor WHERE ts >= ? AND ts < ?').get(hourTs, nextHour);

    if (row && row.cnt > 0) {
        db.prepare('INSERT OR REPLACE INTO sensor_hourly (hour_ts, t_avg, h_avg, v_avg, i_avg, pm1_avg, pm25_avg, pm10_avg, co_avg, voc_avg, nox_avg, sample_count) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)').run(hourTs, row.t, row.h, row.v, row.i_, row.pm1, row.pm25, row.pm10, row.co, row.voc, row.nox, row.cnt);
        node.warn('[HOURLY] ' + hourTs + ' -> ' + row.cnt + ' samples');
    }

    // Rolling 24h
    const recent = db.prepare('SELECT pm25_avg, pm10_avg, co_avg, voc_avg, nox_avg FROM sensor_hourly ORDER BY hour_ts DESC LIMIT 24').all();
    const avgOf = (arr, k) => {
        const v = arr.map(r => r[k]).filter(x => x != null && x > 0 && !isNaN(x));
        return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
    };

    const pm25_avg = avgOf(recent, 'pm25_avg');
    const pm10_avg = avgOf(recent, 'pm10_avg');
    const co_avg = avgOf(recent.slice(0, 8), 'co_avg');
    const voc_avg = avgOf(recent, 'voc_avg');
    const nox_avg = avgOf(recent, 'nox_avg');

    const aqi = Math.max(subIdx(pm25_avg || 0, PM25_BP), subIdx(pm10_avg || 0, PM10_BP), subIdx(co_avg || 0, CO_BP));
    const level = getLevel(aqi);
    const status = recent.length >= 18 ? 'valid' : 'partial';

    // FIX: lưu giờ VN, không dùng toISOString (trả UTC)
    const vnTs = fmt(now);

    db.prepare('INSERT INTO aqi_snapshot (hour_ts, aqi, level, pm25_avg, pm10_avg, co_avg, voc_avg, nox_avg, hours_count, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)').run(vnTs, aqi, level, pm25_avg, pm10_avg, co_avg, voc_avg, nox_avg, recent.length, status);

    // FIX: cache cũng dùng giờ VN
    global.set('aqi_cache', { aqi, level, components: { pm25_avg, pm10_avg, co_avg, voc_avg, nox_avg }, hours_count: recent.length, status, computed_at: vnTs });

    node.warn('[AQI] ' + aqi + ' (' + level + ') - ' + recent.length + '/24h - ' + vnTs);
    db.close();
    return null;
} catch (e) {
    try { db.close(); } catch (_) { }
    node.error('[CRON] ' + e.message);
    return null;
}

let db = new Database('/root/Documents/data.db');
