let lastDataTs = null;
let minutesAgo = null;

try {
    const row = db.prepare('SELECT MAX(ts) as latest FROM sensor').get();
    if (row && row.latest) {
        lastDataTs = row.latest;
        const latestMs = new Date(String(lastDataTs).replace(' ', 'T')).getTime();
        minutesAgo = Math.floor((Date.now() - latestMs) / 60000);
        if (minutesAgo > 30) isStale = true;
    } else {
        isStale = true;
    }
} catch (e) {
    node.error('[AQI] DB error: ' + e.message);
} finally {
    db.close();
