if (isStale) {
    global.set('aqi_cache', null);

    // Format thời gian dễ đọc
    let timeText = '';
    if (!lastDataTs) {
        timeText = 'Chưa có dữ liệu từ trạm';
    } else if (minutesAgo < 60) {
        timeText = `Dữ liệu cuối cách đây ${minutesAgo} phút`;
    } else if (minutesAgo < 1440) {
        const h = Math.floor(minutesAgo / 60);
        const m = minutesAgo % 60;
        timeText = `Dữ liệu cuối cách đây ${h} giờ${m > 0 ? ' ' + m + ' phút' : ''}`;
    } else {
        const d = Math.floor(minutesAgo / 1440);
        const h = Math.floor((minutesAgo % 1440) / 60);
        timeText = `Dữ liệu cuối cách đây ${d} ngày${h > 0 ? ' ' + h + ' giờ' : ''}`;
    }

    msg.statusCode = 200;
    msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-cache' };
    msg.payload = {
        aqi: null,
        status: 'stale',
        last_data: lastDataTs,
        minutes_ago: minutesAgo,
        message: timeText
    };
    return msg;
}

