function toInt(x) {
    const n = parseInt(x, 10);
    return Number.isFinite(n) ? n : null;
}

function toFloat(x) {
    const n = parseFloat(x);
    return Number.isFinite(n) ? n : null;
}

function fmtVal(v) {
    if (v === null || v === undefined) return 'null';
    if (Number.isNaN(v)) return 'NaN';
    return String(v);
}

function pushBad(bad, name, val) {
    bad.push(`${name}=${fmtVal(val)}`);
}

// I2C devices: 0 hoặc -1 => loại
function badI2C(name, val, bad) {
    if (val === null || val === undefined || Number.isNaN(val) || val <= 0) {
        pushBad(bad, name, val);
        return true;
    }
    return false;
}

// ZE07, PMS: âm => loại
function badNeg(name, val, bad) {
    if (val === null || val === undefined || Number.isNaN(val) || val < 0) {
        pushBad(bad, name, val);
        return true;
    }
    return false;
}

// RSSI: dương => loại
function badRssi(name, val, bad) {
    if (val === null || val === undefined || Number.isNaN(val) || val > 0) {
        pushBad(bad, name, val);
        return true;
    }
    return false;
}

function validateRow(row) {
    const bad = [];

    // Các thiết bị I2C: 0 hoặc -1 là rác
    badI2C('t', row.t, bad);
    badI2C('h', row.h, bad);
    badI2C('p', row.p, bad);
    badI2C('v', row.v, bad);
    badI2C('i', row.i, bad);

    badI2C('voc', row.voc, bad);
    badI2C('nox', row.nox, bad);

    badI2C('maxv', row.maxv, bad);
    badI2C('minv', row.minv, bad);
    badI2C('maxi', row.maxi, bad);
    badI2C('mini', row.mini, bad);

    // ZE07: âm là lỗi
    badNeg('co', row.co, bad);

    // PMS: âm là lỗi
    badNeg('pm1', row.pm1, bad);
    badNeg('pm25', row.pm25, bad);
    badNeg('pm10', row.pm10, bad);

    // RSSI: dương là lỗi
    badRssi('rssi', row.rssi, bad);

    // SNR: giữ nguyên, chỉ cần có số
    if (row.snr === null || row.snr === undefined || Number.isNaN(row.snr)) {
        pushBad(bad, 'snr', row.snr);
    }

    return bad;
}

