    const quotedTable = quote(table);

    const columnsInfo = db.prepare(
        `PRAGMA table_info(${quotedTable})`
    ).all();

    const columns = columnsInfo.map(c => c.name);

    if (!columns.length) {
        msg.statusCode = 400;
        msg.payload = { error: 'No columns found' };
        return msg;
    }

    // ===== 5. DYNAMIC SEARCH =====
    let where = '';
    const params = [];

    if (q) {
        where = 'WHERE (' + columns.map(c =>
            `CAST(${quote(c)} AS TEXT) LIKE ?`
        ).join(' OR ') + ')';

        params.push(...columns.map(() => `%${q}%`));
    }

    // ===== 6. COUNT RECORDS =====
    const total = db.prepare(`
        SELECT COUNT(*) AS total
        FROM ${quotedTable}
        ${where}
    `).get(...params).total;

    // ===== 7. DYNAMIC ORDER =====
    const primaryKeys = columnsInfo
        .filter(c => c.pk > 0)
        .sort((a, b) => a.pk - b.pk);

    const orderBy = primaryKeys.length
        ? primaryKeys.map(c => `${quote(c.name)} DESC`).join(', ')
        : 'rowid DESC';

    // ===== 8. GET DATA =====
    const rows = db.prepare(`
        SELECT *
        FROM ${quotedTable}
        ${where}
        ORDER BY ${orderBy}
        LIMIT ? OFFSET ?
    `).all(...params, limit, offset);

    // ===== 9. RESPONSE =====
    msg.statusCode = 200;
    msg.payload = {
        table,
        columns,
        rows,
        total,
        limit,
        offset,
        q
    };

    node.warn(
        `[DB VIEWER] user=${sess.username} role=${sess.role} table=${table}, rows=${rows.length}, total=${total}`
    );

    return msg;

} catch (e) {
    node.error(`[DB VIEWER] ${e.message}`);

    msg.statusCode = 500;
    msg.payload = { error: e.message };

    return msg;

} finally {
    if (db) db.close();
}
